function LocalCheck(c, e=(u,v)):
    return c[u] != c[v]            # O(1): two symbol reads

function GlobalCheck(E, c):
    for each edge e in E:
        if not LocalCheck(c, e):
            return REJECT
    return ACCEPT                  # O(|E|)

